{
  "status": "NEED_INFO",
  "summary": "Đề bài yêu cầu xây dựng một website bán hàng hoàn chỉnh với giao diện đẹp và đầy đủ tính năng. Sinh viên được tự do lựa chọn công nghệ và hình thức làm việc (cá nhân hoặc nhóm) để nộp sản phẩm vào cuối kỳ.",
  "deadline": null,
  "requirements": [
    {
      "content": "Xây dựng website chuyên về lĩnh vực bán hàng",
      "quote": "Làm một trang web bán hàng"
    },
    {
      "content": "Giao diện phải có tính thẩm mỹ",
      "quote": "cho đẹp"
    },
    {
      "content": "Phải có toàn bộ các chức năng nghiệp vụ của một web bán hàng",
      "quote": "có đầy đủ các chức năng cần thiết"
    }
  ],
  "constraints": [
    {
      "content": "Tùy chọn công nghệ sử dụng miễn là hợp lý",
      "quote": "Dùng công nghệ nào cũng được miễn là phù hợp"
    },
    {
      "content": "Linh hoạt về số lượng thành viên tham gia",
      "quote": "Làm nhóm hoặc cá nhân tùy ý"
    }
  ],
  "deliverables": [
    {
      "content": "Sản phẩm phần mềm (website) hoàn thiện",
      "quote": "điểm tùy theo mức độ hoàn thiện của sản phẩm"
    }
  ],
  "grading_criteria": [
    {
      "content": "Điểm số tỷ lệ thuận với mức độ hoàn chỉnh của các chức năng và sản phẩm",
      "quote": "điểm tùy theo mức độ hoàn thiện của sản phẩm"
    }
  ],
  "missing_info": [
    "Thời gian nộp bài cụ thể (ngày/tháng/năm)",
    "Danh sách các chức năng bắt buộc phải có (ví dụ: Thanh toán, Giỏ hàng, Admin, Quản lý kho...)",
    "Yêu cầu về tài liệu đi kèm (Báo cáo word, sơ đồ thiết kế Database, slide thuyết trình)",
    "Cách thức nộp bài (Nộp mã nguồn qua LMS, link Github, hay triển khai lên host)",
    "Số lượng thành viên tối đa nếu làm nhóm"
  ],
  "questions": [
    "Bạn dự định làm cá nhân hay nhóm? Nếu làm nhóm thì có mấy người?",
    "Bạn đã có dự định sử dụng ngôn ngữ hay framework nào chưa (ví dụ: HTML/CSS/JS thuần, React, PHP, hay Java)?",
    "Ngày cuối cùng của học kỳ bạn phải nộp bài là ngày nào?",
    "Thầy/cô có cung cấp bảng tiêu chí (rubric) chấm điểm chi tiết không?"
  ],
  "ambiguities": [
    {
      "content": "Tiêu chuẩn 'đẹp' mang tính chủ quan, không có thước đo cụ thể",
      "quote": "cho đẹp"
    },
    {
      "content": "Cụm từ 'chức năng cần thiết' không xác định rõ phạm vi tối thiểu (MVP)",
      "quote": "có đầy đủ các chức năng cần thiết"
    }
  ],
  "contradictions": [],
  "invalid_data": [],
  "injection_flags": [],
  "refusal_reason": null,
  "plan": [
    {
      "step": 1,
      "task": "Xác nhận lại yêu cầu: Chốt danh sách tính năng (Scope) và công nghệ sử dụng",
      "due": "Ngày 1-2"
    },
    {
      "step": 2,
      "task": "Thiết kế: Vẽ giao diện (Figma) và thiết kế Cơ sở dữ liệu (ERD)",
      "due": "Ngày 3-5"
    },
    {
      "step": 3,
      "task": "Lập trình Back-end: Xây dựng API và xử lý dữ liệu",
      "due": "Tuần 2"
    },
    {
      "step": 4,
      "task": "Lập trình Front-end: Xây dựng giao diện và kết nối API",
      "due": "Tuần 3"
    },
    {
      "step": 5,
      "task": "Kiểm thử và Hoàn thiện: Fix lỗi, tối ưu giao diện và đóng gói nộp bài",
      "due": "Tuần 4/Trước hạn nộp"
    }
  ]
}
